import{_ as u,a0 as i,w as r,s,ao as l,I as p,x as o,a1 as a,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"如何深度定制 Ubuntu 面板的时间日期显示格式 | LCTT x X-CMD","titleTemplate":false,"description":"如何深度定制 Ubuntu 面板的时间日期显示格式 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何深度定制 Ubuntu 面板的时间日期显示格式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何深度定制 Ubuntu 面板的时间日期显示格式 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151208 How to Customize Time and Date Format in Ubuntu Panel","title":"如何深度定制 Ubuntu 面板的时间日期显示格式","tag":"201512","desc":""},"relativePath":"201512/20151208 How to Customize Time and Date Format in Ubuntu Panel.md","filePath":"[post].md"}'),m={name:"201512/20151208 How to Customize Time and Date Format in Ubuntu Panel.md"};function d(g,t,b,f,T,x){const n=i("Link");return r(),s("div",null,[t[13]||(t[13]=l(`<h1 id="如何深度定制-ubuntu-面板的时间日期显示格式" tabindex="-1">如何深度定制 Ubuntu 面板的时间日期显示格式 <a class="header-anchor" href="#如何深度定制-ubuntu-面板的时间日期显示格式" aria-label="Permalink to “如何深度定制 Ubuntu 面板的时间日期显示格式”">​</a></h1><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/08/ubuntu_tips1.png" alt="时间日期格式"></p><p>尽管设置页面里已经有一些选项可以用了，这个快速教程会向你展示如何更加深入地自定义 Ubuntu 面板上的时间和日期指示器。</p><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/12/custom-timedate.jpg" alt="自定义世间日期"></p><p>在开始之前，在 Ubuntu 软件中心搜索并安装 <strong>dconf Editor</strong>。然后启动该软件并按以下步骤执行：</p><p><strong>1、</strong> 当 dconf Editor 启动后，导航至 <strong>com -&gt; canonical -&gt; indicator -&gt; datetime</strong>。将 <strong>time-format</strong> 的值设置为 <strong>custom</strong>。</p><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/12/time-format.jpg" alt="自定义时间格式"></p><p>你也可以通过终端里的命令完成以上操作：</p><pre><code>gsettings set com.canonical.indicator.datetime time-format &#39;custom&#39;
</code></pre><p><strong>2、</strong> 现在你可以通过编辑 <strong>custom-time-format</strong> 的值来自定义时间和日期的格式。</p><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/12/customize-timeformat.jpg" alt="自定义-时间格式"></p><p>你也可以通过命令完成：(LCTT 译注：将 FORMAT_VALUE_HERE 替换为所需要的格式值)</p><pre><code>gsettings set com.canonical.indicator.datetime custom-time-format &#39;FORMAT_VALUE_HERE&#39;
</code></pre><p>以下是参数含义：</p><ul><li>%a = 星期名缩写</li><li>%A = 星期名完整拼写</li><li>%b = 月份名缩写</li><li>%B = 月份名完整拼写</li><li>%d = 每月的日期</li><li>%l = 小时 ( 1..12)， %I = 小时 (01..12)</li><li>%k = 小时 ( 1..23)， %H = 小时 (01..23)</li><li>%M = 分钟 (00..59)</li><li>%p = 午别，AM 或 PM， %P = am 或 pm.</li><li>%S = 秒 (00..59)</li></ul><p>可以打开终端键入命令 <code>man date</code> 并执行以了解更多细节。</p><p>一些自定义时间日期显示格式值的例子：</p><p><strong>%a %H:%M %m/%d/%Y</strong></p><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/12/exam-1.jpg" alt="%a %H:%M %m/%d/%Y"></p><p><strong>%a %r %b %d or %a %I:%M:%S %p %b %d</strong></p><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/12/exam-2.jpg" alt="%a %r %b %d or %a %I:%M:%S %p %b %d"></p><p><strong>%a %-d %b %l:%M %P %z</strong></p><p><img src="http://ubuntuhandbook.org/wp-content/uploads/2015/12/exam-3.jpg" alt="%a %-d %b %l:%M %P %z"></p><hr>`,24)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),a(n,{href:"http://ubuntuhandbook.org/index.php/2015/12/time-date-format-ubuntu-panel/"},{default:e(()=>[...t[0]||(t[0]=[o("http://ubuntuhandbook.org/index.php/2015/12/time-date-format-ubuntu-panel/",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=o("作者：",-1)),a(n,{href:"http://ubuntuhandbook.org/index.php/about/"},{default:e(()=>[...t[2]||(t[2]=[o("Ji m",-1)])]),_:1}),t[6]||(t[6]=o(" 译者：",-1)),a(n,{href:"https://github.com/alim0x"},{default:e(()=>[...t[3]||(t[3]=[o("alim0x",-1)])]),_:1}),t[7]||(t[7]=o(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=o("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[o("Linux中国",-1)])]),_:1}),t[12]||(t[12]=o(" 荣誉推出",-1))])])}const c=u(m,[["render",d]]);export{_ as __pageData,c as default};
